#!/usr/bin/env node
/* Refresh reconnect-rc-icons-wf.snapshot.json from a ReConnect checkout (dev-only, host-side).

   Why a snapshot. The clerkship site and ReConnect each vendor their OWN copy of the same Lucide
   release (C0 decision D-set: one set, no shared package). tests/fd-icons-reconnect-drift.test.mjs
   proves the two copies still draw every shared glyph identically -- but CI here has no ReConnect
   checkout, so the test reads this committed snapshot of ReConnect's Lucide-derived `wf-*` subset,
   stamped with the commit it was read from. This script is the only thing that writes it.

     node refresh_reconnect_icon_snapshot.mjs --repo ~/Code/reconnect-psychiatry-system --rev <sha>
     node refresh_reconnect_icon_snapshot.mjs --repo <path> --rev <sha> --check   # exit 1 on drift

   --rev defaults to the repo's origin/main. It reads the file at that commit with `git show`
   (never the working tree, so an uncommitted edit cannot leak into the stamp), evaluates the UMD
   module in an isolated vm context (no require, no fs, no network), and keeps every ICONS entry
   that carries a `lucide` field. Read-only against ReConnect: it never writes there. */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const HERE = dirname(fileURLToPath(import.meta.url));
export const SNAPSHOT_PATH = join(HERE, 'reconnect-rc-icons-wf.snapshot.json');
export const SOURCE_FILE = 'tools-suite/shared-libs/rc-icons.js';

/** Evaluate rc-icons.js source and return its Lucide-derived subset, sorted by name. */
export function extractWayfinding(source) {
  const sandbox = { module: { exports: {} } };
  vm.runInNewContext(source, sandbox, { timeout: 2000, filename: 'rc-icons.js' });
  const api = sandbox.module.exports;
  if (!api || typeof api.ICONS !== 'object') throw new Error('rc-icons.js exported no ICONS');
  if (typeof api.LUCIDE_VERSION !== 'string') throw new Error('rc-icons.js exported no LUCIDE_VERSION');
  const icons = {};
  for (const name of Object.keys(api.ICONS).sort()) {
    const entry = api.ICONS[name];
    if (entry && typeof entry.lucide === 'string') icons[name] = { lucide: entry.lucide, d: entry.d };
  }
  return { lucideVersion: api.LUCIDE_VERSION, icons };
}

export function serialize(snapshot) {
  return JSON.stringify(snapshot, null, 2) + '\n';
}

function arg(name, fallback) {
  const at = process.argv.indexOf(name);
  return at > -1 && process.argv[at + 1] ? process.argv[at + 1] : fallback;
}

function main() {
  const repo = arg('--repo', '');
  if (!repo || !existsSync(join(repo, '.git'))) {
    console.error('usage: refresh_reconnect_icon_snapshot.mjs --repo <ReConnect checkout> [--rev <sha>] [--check]');
    process.exit(2);
  }
  const rev = execFileSync('git', ['-C', repo, 'rev-parse', arg('--rev', 'origin/main')], { encoding: 'utf8' }).trim();
  const source = execFileSync('git', ['-C', repo, 'show', `${rev}:${SOURCE_FILE}`], { encoding: 'utf8', maxBuffer: 8 << 20 });
  const { lucideVersion, icons } = extractWayfinding(source);
  const snapshot = {
    _note: 'Generated by refresh_reconnect_icon_snapshot.mjs. Do not edit by hand. ReConnect\'s '
      + 'Lucide-derived `wf-*` glyphs (rc-icons.js entries with a `lucide` field), read at '
      + '`source.commit`. tests/fd-icons-reconnect-drift.test.mjs compares them with this repo\'s '
      + 'vendored subset by upstream Lucide name.',
    source: { repo: 'jmoss333/reconnect-psychiatry-system', path: SOURCE_FILE, commit: rev },
    lucideVersion,
    icons,
  };
  const out = serialize(snapshot);
  const existing = existsSync(SNAPSHOT_PATH) ? readFileSync(SNAPSHOT_PATH, 'utf8') : '';
  if (process.argv.includes('--check')) {
    console.log(out === existing ? 'reconnect icon snapshot: up to date' : 'reconnect icon snapshot: WOULD CHANGE');
    process.exit(out === existing ? 0 : 1);
  }
  if (out !== existing) writeFileSync(SNAPSHOT_PATH, out);
  console.log(`reconnect icon snapshot: ${Object.keys(icons).length} wf-* glyph(s) at ${rev.slice(0, 12)} (Lucide ${lucideVersion})`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
